ALTER TABLE tenants ADD COLUMN business_mode TEXT NOT NULL DEFAULT 'appointments' CHECK(business_mode IN ('appointments','catalog_inquiry'));
ALTER TABLE tenants ADD COLUMN storefront_status TEXT NOT NULL DEFAULT 'published' CHECK(storefront_status IN ('draft','published','unpublished'));
ALTER TABLE tenants ADD COLUMN template TEXT NOT NULL DEFAULT 'atelier' CHECK(template IN ('atelier','studio','boutique'));
ALTER TABLE tenants ADD COLUMN palette TEXT NOT NULL DEFAULT 'forest' CHECK(palette IN ('forest','clay','ink'));
ALTER TABLE tenants ADD COLUMN headline TEXT NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN contact_phone TEXT;
ALTER TABLE tenants ADD COLUMN locality TEXT NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN policy_text TEXT NOT NULL DEFAULT '';
ALTER TABLE tenants ADD COLUMN inquiries_enabled INTEGER NOT NULL DEFAULT 1 CHECK(inquiries_enabled IN (0,1));
ALTER TABLE tenants ADD COLUMN is_demo INTEGER NOT NULL DEFAULT 0 CHECK(is_demo IN (0,1));
ALTER TABLE tenants ADD COLUMN onboarding_started_at INTEGER;
ALTER TABLE tenants ADD COLUMN first_published_at INTEGER;
CREATE TABLE catalog_items(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',variant TEXT NOT NULL DEFAULT '',price_centimes INTEGER NOT NULL CHECK(price_centimes BETWEEN 0 AND 10000000),availability TEXT NOT NULL DEFAULT 'ask' CHECK(availability IN ('ask','available','unavailable')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),UNIQUE(tenant_id,id));
CREATE TABLE inquiries(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),item_id TEXT NOT NULL,customer_id TEXT NOT NULL,variant TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20),price_centimes INTEGER NOT NULL CHECK(price_centimes BETWEEN 0 AND 200000000),note TEXT NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','fulfilled','cancelled')),consent_contact INTEGER NOT NULL CHECK(consent_contact=1),consent_marketing INTEGER NOT NULL DEFAULT 0 CHECK(consent_marketing IN (0,1)),created_at INTEGER NOT NULL,fulfilled_at INTEGER,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,item_id) REFERENCES catalog_items(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TRIGGER inquiry_guard BEFORE INSERT ON inquiries BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants t JOIN catalog_items i ON i.tenant_id=t.id WHERE t.id=NEW.tenant_id AND t.active=1 AND t.business_mode='catalog_inquiry' AND t.storefront_status='published' AND t.paused=0 AND t.inquiries_enabled=1 AND i.id=NEW.item_id AND i.active=1 AND i.availability!='unavailable' AND NEW.price_centimes=i.price_centimes*NEW.quantity) THEN RAISE(ABORT,'inquiry_unavailable') END; END;
CREATE TABLE launch_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,event_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,event_key));
CREATE TRIGGER inquiry_event AFTER INSERT ON inquiries BEGIN INSERT INTO launch_events VALUES ('inquiry:'||NEW.id,NEW.tenant_id,'inquiry_created','inquiry:'||NEW.id,NEW.created_at); END;
CREATE TRIGGER booking_launch_event AFTER INSERT ON bookings BEGIN INSERT INTO launch_events VALUES ('booking:'||NEW.id,NEW.tenant_id,'booking_created','booking:'||NEW.id,NEW.created_at); END;
CREATE TRIGGER completed_launch_event AFTER UPDATE OF status ON bookings WHEN NEW.status='completed' AND OLD.status!='completed' BEGIN INSERT OR IGNORE INTO launch_events VALUES ('completed:'||NEW.id,NEW.tenant_id,'visit_completed','completed:'||NEW.id,unixepoch()*1000); END;
CREATE TRIGGER payment_launch_event AFTER INSERT ON payment_records BEGIN INSERT INTO launch_events VALUES ('payment:'||NEW.id,NEW.tenant_id,'merchant_payment_recorded','payment:'||NEW.id,NEW.created_at); END;
CREATE INDEX inquiries_tenant ON inquiries(tenant_id,created_at);
CREATE INDEX launch_events_tenant ON launch_events(tenant_id,kind,created_at);
CREATE TRIGGER booking_mode_guard BEFORE INSERT ON bookings BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM tenants WHERE id=NEW.tenant_id AND business_mode='appointments' AND (storefront_status='published' OR NEW.source IN ('manual','whatsapp','walk_in'))) THEN RAISE(ABORT,'stale_configuration') END; END;
